INSERT INTO banks(id,title,data_json,created_at) VALUES('demo-v1','原創示範題', '{"version":1,"questions":[{"id":"v1","type":"vocabulary","prompt":"The island has a hidden treasure. What does “treasure” mean?","choices":["寶藏","森林","橋梁","天氣"],"answerIndex":0,"explanation":"treasure 是「寶藏」。hidden treasure 指藏起來的寶藏。","points":10,"word":"treasure","meaning":"寶藏"},{"id":"v2","type":"vocabulary","prompt":"Which word means「勇敢的」?","choices":["quiet","brave","hungry","cloudy"],"answerIndex":1,"explanation":"brave 是「勇敢的」；quiet 是安靜的，hungry 是飢餓的，cloudy 是多雲的。","points":10,"word":"brave","meaning":"勇敢的"},{"id":"v3","type":"vocabulary","prompt":"We cross the river on a _____.","choices":["cloud","flower","bridge","star"],"answerIndex":2,"explanation":"bridge 是「橋梁」。cross the river 表示渡過河流。","points":10,"word":"bridge","meaning":"橋梁"},{"id":"g1","type":"grammar","prompt":"Look! The little fox _____ under the tree.","choices":["sleep","sleeps","sleeping","is sleeping"],"answerIndex":3,"explanation":"Look! 提示正在發生的動作，使用現在進行式 be + V-ing。主詞是單數，所以用 is sleeping。","points":10},{"id":"r1","type":"reading","passage":"Mia finds a small bird near the river. Its wing is hurt. She takes it to a safe tree house and brings it water. The next morning, the bird can fly again.","prompt":"Why does Mia take the bird to the tree house?","choices":["To teach it to sing.","To help the hurt bird.","To find a treasure.","To meet her friends."],"answerIndex":1,"explanation":"文中提到鳥的翅膀受傷（Its wing is hurt），Mia 將牠帶到安全的樹屋並給水，因此目的是幫助受傷的小鳥。","points":10},{"id":"l1","type":"listening","speech":"Go across the bridge and turn left. The treasure is behind the big tree.","prompt":"Where is the treasure?","choices":["Under the bridge.","Next to the river.","Behind the big tree.","In the tree house."],"answerIndex":2,"explanation":"音訊說 The treasure is behind the big tree.，所以寶藏在大樹後方。behind 表示「在……後面」。","points":10}]}',0);
